<script setup lang="ts">import type { PublicHomePayload } from '#shared/contracts/public-home'; const props = defineProps<{ hero: PublicHomePayload['hero'] }>(); const active = ref(0); const current = computed(() => props.hero[active.value] || null); function move(step: number) { if (!props.hero.length) return; active.value = (active.value + step + props.hero.length) % props.hero.length }</script>
<template><section v-if="current" class="home-hero" aria-labelledby="home-title"><div class="home-hero__media"><a :href="current.href"><img :src="current.image" :alt="current.name" fetchpriority="high" width="1600" height="720"><span aria-hidden="true" /></a></div><div class="pts-container home-hero__copy"><p class="home-hero__kicker">Phân phối thiết bị · Tư vấn · Thi công lắp đặt</p><h1 id="home-title"><span>Thiết bị và giải pháp</span> năng lượng mặt trời</h1><p>Phúc Thịnh Solar cung cấp thiết bị chiếu sáng, điện mặt trời và lưu trữ năng lượng; tư vấn phương án phù hợp cho gia đình, doanh nghiệp và công trình.</p><div class="home-actions"><a class="home-button" href="#danh-muc-thiet-bi">Xem sản phẩm</a><a class="home-link home-link--light" href="#yeu-cau-tu-van">Tư vấn lắp đặt</a></div></div><div v-if="hero.length > 1" class="home-hero__controls"><button type="button" aria-label="Banner trước" @click="move(-1)">←</button><span>{{ String(active + 1).padStart(2, '0') }} / {{ String(hero.length).padStart(2, '0') }}</span><button type="button" aria-label="Banner tiếp theo" @click="move(1)">→</button></div><p class="home-hero__tile"><strong>{{ current.name }}</strong><span>{{ current.description }}</span></p></section></template>
